package com.security.__PKG__.ui.components

// Canonical source: android-foundation/design-system/components/GlassBottomNavBar.kt
// (extracted from CallUp's bottom bar). Copied into every app generated by `app`, with __PKG__
// replaced. Improve it in android-foundation, not in a single app.

import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Icon
import androidx.compose.material3.NavigationBar
import androidx.compose.material3.NavigationBarItem
import androidx.compose.material3.NavigationBarItemDefaults
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.unit.dp
import com.security.__PKG__.ui.theme.Accent
import com.security.__PKG__.ui.theme.BgCard
import com.security.__PKG__.ui.theme.GlassCard
import com.security.__PKG__.ui.theme.TextSecondary

/** One destination of [GlassBottomNavBar]. */
data class NavTab(val label: String, val icon: ImageVector)

/**
 * Floating liquid-glass bottom navigation: inset from the screen edges and fully rounded (28dp).
 *
 * It is a [GlassCard] like the cards above it, so pass it as `Scaffold(bottomBar = …)` INSIDE the
 * screen's `ScreenWallpaperBackdrop`: with liquid glass on it then refracts the real wallpaper
 * behind it. With glass off it is a flat BgCard tray — same color as the cards. Never add a border/hairline to it.
 */
@Composable
fun GlassBottomNavBar(
    tabs: List<NavTab>,
    selectedIndex: Int,
    onSelect: (Int) -> Unit,
    modifier: Modifier = Modifier,
) {
    GlassCard(
        modifier = modifier.padding(start = 16.dp, end = 16.dp, top = 4.dp, bottom = 8.dp),
        radius = 28.dp,
        fallbackColor = BgCard,
    ) {
        NavigationBar(containerColor = Color.Transparent) {
            val tabColors = NavigationBarItemDefaults.colors(
                selectedIconColor = Accent,
                selectedTextColor = Accent,
                // Same 12 % accent wash as the "+" button and the stats pill.
                indicatorColor = Accent.copy(alpha = 0.12f),
                unselectedIconColor = TextSecondary,
                unselectedTextColor = TextSecondary,
            )
            tabs.forEachIndexed { index, tab ->
                NavigationBarItem(
                    selected = index == selectedIndex,
                    onClick = { onSelect(index) },
                    icon = { Icon(tab.icon, contentDescription = null) },
                    label = { Text(tab.label) },
                    colors = tabColors,
                )
            }
        }
    }
}
